        );
    }

    #[test]
    fn assignee_and_receipt_uniques_match_contract_keys() {
        assert_eq!(
            index_named(
                &assignee_indexes(),
                "uk_approval_instance_assignees_instance_node"
            )
            .keys,
            doc! { "process_instance_id": 1, "node_key": 1 }
        );
        assert_eq!(
            index_named(&receipt_indexes(), APPROVAL_COMMAND_RECEIPT_IDEMPOTENCY_INDEX,).keys,
            doc! { "command_kind": 1, "scope_id": 1, "idempotency_key": 1 }
        );
        assert_eq!(
            index_named(&receipt_indexes(), APPROVAL_COMMAND_RECEIPT_IDEMPOTENCY_INDEX,)
                .options
                .as_ref()
                .unwrap()
                .unique,
            Some(true)
        );
    }

    fn index_named<'a>(indexes: &'a [mongodb::IndexModel], name: &str) -> &'a mongodb::IndexModel {
        indexes
            .iter()
            .find(|index| index.options.as_ref().and_then(|options| options.name.as_deref()) == Some(name))
            .unwrap_or_else(|| panic!("missing index {name}"))
    }
}

//! 域 D02 `document_registry` 的索引声明：business_document、document_relation、document_participant、workflow_action。
//!
//! 集合名常量取 `DocumentRegistryExt` 关联常量（唯一权威来源，conventions §4.3）：
//! `indexes/` 与 `repository/` 均为冻结声明下的私有子树，模块路径无法互相引用，
//! 关联常量随 trait 公开可达，两侧共用同一值，禁止字面量重复。

use mongodb::{
    bson::{doc, Document},
    options::IndexOptions,
    Database, IndexModel,
};

use crate::repository::DocumentRegistryExt;
use persistence_core::Result;

/// `business_document` 集合名。
pub const BUSINESS_DOCUMENTS: &str = <mongodb::Database as DocumentRegistryExt>::BUSINESS_DOCUMENTS;
/// `document_relation` 集合名。
pub const DOCUMENT_RELATIONS: &str = <mongodb::Database as DocumentRegistryExt>::DOCUMENT_RELATIONS;
/// `document_participant` 集合名。
pub const DOCUMENT_PARTICIPANTS: &str = <mongodb::Database as DocumentRegistryExt>::DOCUMENT_PARTICIPANTS;
/// `workflow_action` 集合名。
pub const WORKFLOW_ACTIONS: &str = <mongodb::Database as DocumentRegistryExt>::WORKFLOW_ACTIONS;

/// 创建本域集合的幂等命名索引。
///
/// 逐条落地数据模型 §6.1「必需约束与索引」：
/// - `business_document`：`id` 全量唯一（空编号草稿也只能有一行）；非空
///   `(document_type, document_no)` 部分唯一（空编号草稿可并存）；非空
///   `document_no` 全局搜索索引；
/// - `document_relation`：`(from_document_id, to_document_id, relation_type)` 唯一，
///   `to_document_id + relation_type` 反向查询索引；
/// - `workflow_action`：`document_id + created_at` 历史索引、`actor_id + created_at`
///   审计索引（§6.1 的 `recorded_at` 由 `BaseModel.created_at` 承载）；
/// - `document_participant`：追加式参与记录（§4.6 只追加不删除）无自然业务唯一键，
///   用 `id` 唯一索引防止重复身份静默写入。
///
/// # 参数
/// * `db` - 目标 MongoDB 数据库
///
/// # 错误
/// 当已有数据违反唯一约束或 MongoDB 无法创建索引时返回错误。
pub async fn ensure(db: &Database) -> Result<()> {
    create_indexes(db, BUSINESS_DOCUMENTS, business_document_indexes()).await?;
    create_indexes(db, DOCUMENT_RELATIONS, document_relation_indexes()).await?;
    create_indexes(db, DOCUMENT_PARTICIPANTS, document_participant_indexes()).await?;
    create_indexes(db, WORKFLOW_ACTIONS, workflow_action_indexes()).await?;
    Ok(())
}

/// 为单个集合创建一组幂等命名索引。
async fn create_indexes(db: &Database, collection: &str, indexes: Vec<IndexModel>) -> Result<()> {
    db.collection::<Document>(collection)
        .create_indexes(indexes)
        .await?;
    Ok(())
}

/// 返回 `business_document` 的稳定 `id`、非空编号身份约束与搜索索引。
fn business_document_indexes() -> Vec<IndexModel> {
    vec![
        unique_index("uk_business_documents_id", doc! { "id": 1 }),
        unique_partial_index(
            "uk_business_documents_identity",
            doc! { "document_type": 1, "document_no": 1 },
            non_empty_document_no_filter(),
        ),
        named_partial_index(
            "idx_business_documents_no",
