            non_empty_document_no_filter(),
        ),
    ]
}

/// 非空 `document_no` 部分过滤；空字符串草稿不进入唯一或搜索索引。
fn non_empty_document_no_filter() -> Document {
    doc! { "document_no": { "$gt": "" } }
